mapper.select:
SELECT s.id, s.name, s.no, s.gender, s.phone, s.id_card, s.is_college, s.address, s.degree, s.graduation_date, s.clazz_id, s.violation_count, s.violation_score, s.create_time, s.update_time, c.name FROM student AS s LEFT JOIN clazz AS c ON s.clazz_id = c.id
s.name LIKE CONCAT('%', #{name}, '%')
AND s.degree = #{degree}
AND s.clazz_id = #{clazzId}
ORDER BY s.update_time DESC
